       "Version": "2012-10-17",
       "Statement": [
           {
               "Effect": "Allow",
               "Action": "s3:*",
               "Resource": "arn:aws:s3:::finance-archive/*",
               "Principal": {
                   "AWS": "arn:aws:iam::<account-id>:group/data-analytics"
               }
           }
       ]
   }

   Replace `<account-id>` with your AWS account ID.

